import sys
sys.setrecursionlimit(300000)

def dfs(node, parent, graph, saved):
    max_saved = 0
    for child in graph[node]:
        if child != parent:
            child_saved = dfs(child, node, graph, saved)
            max_saved += child_saved
    if max_saved == 0 and node != 1:
        return 1
    return max_saved

def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        graph = [[] for _ in range(n + 1)]
        for _ in range(n - 1):
            u, v = map(int, input().split())
            graph[u].append(v)
            graph[v].append(u)

        saved = [0] * (n + 1)
        for node in range(1, n + 1):
            if len(graph[node]) == 1:
                saved[node] = 1

        result = 0
        for node in range(1, n + 1):
            if saved[node] == 0:
                for child in graph[node]:
                    if saved[child] == 1:
                        saved[node] = 2
                        result += 1
                        break

        print(n - result - 1)

solve()
